    barEl.style.transform = instant ? 'translateY(0)' : 'translateY(6px)';
    if (instant) barEl.style.display = 'none';
    else setTimeout(() => { if (barEl && hideSeq === barHideSeq) barEl.style.display = 'none'; }, 250);
