      session?.id
      && !isTerminalSessionSummary(session)
      && !isSessionHandled(session.id)
      && session.pageUrl
      && pageMatchesCurrent(session.pageUrl)
      && (session.previewFile || session.sourceFile)
      && Number(session.expectedVariants) > 0
