import { NextRequest, NextResponse } from "next/server";
import { CheckInService } from "@/lib/services/checkInService";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { token, volunteerId = "gate-authority", action = "confirm" } = body;

    if (!token || !String(token).trim()) {
      return NextResponse.json(
        { success: false, error: "QR token or team code is required." },
        { status: 400 }
      );
    }

    const cleanToken = String(token).trim();

    // 1. Action: "lookup" (Roster verification before physical entry)
    if (action === "lookup") {
      const result = await CheckInService.lookupTeam(cleanToken);
      if (!result.success) {
        return NextResponse.json(
          {
            success: false,
            error: result.message,
            alreadyCheckedIn: result.alreadyCheckedIn,
            team: result.team,
          },
          { status: result.alreadyCheckedIn ? 409 : 404 }
        );
      }
      return NextResponse.json({
        success: true,
        message: result.message,
        team: result.team,
      });
    }

    // 2. Action: "confirm" (Marks team as Present in the system)
    const checkInResult = await CheckInService.processCheckIn(
      cleanToken,
      "ev-1",
      volunteerId
    );

    if (!checkInResult.success) {
      return NextResponse.json(
        {
          success: false,
          error: checkInResult.message,
          alreadyCheckedIn: checkInResult.alreadyCheckedIn,
          team: checkInResult.team,
        },
        { status: checkInResult.alreadyCheckedIn ? 409 : 400 }
      );
    }

    return NextResponse.json({
      success: true,
      message: checkInResult.message,
      team: checkInResult.team,
      timestamp: checkInResult.timestamp,
    });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { TeamService } from "@/lib/services/teamService";

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const eventId = searchParams.get("eventId") || "ev-1";
    const format = (searchParams.get("format") || "json").toLowerCase();

    const teams = await TeamService.listTeams(eventId);

    const flattened = teams.flatMap((t) =>
      t.participants.map((p) => ({
        Team_Name: t.name,
        Full_Name: p.full_name,
        Role: p.is_leader ? "Leader" : "Member",
        Email: p.email,
        Mobile_Number: p.mobile_number || "N/A",
        Course: p.course || "N/A",
        Year_Of_Study: p.year_of_study || "N/A",
        Approval_Status: t.status,
        QR_Token: t.qr_token,
        QR_Email_Dispatched: t.qr_email_sent ? "Yes" : "No",
        Attendance_Status: t.check_in_status === "CHECKED_IN" ? "Present" : "Not Checked In",
        Checked_In_At: t.checked_in_at || "N/A",
        Checked_In_By: t.checked_in_by || "N/A",
      }))
    );

    if (format === "csv") {
      if (flattened.length === 0) {
        return new NextResponse("", {
          headers: {
            "Content-Type": "text/csv",
            "Content-Disposition": `attachment; filename="roster_${eventId}.csv"`,
          },
        });
      }

      const headers = Object.keys(flattened[0]).join(",");
      const csvRows = flattened.map((row) =>
        Object.values(row)
          .map((val) => `"${String(val).replace(/"/g, '""')}"`)
          .join(",")
      );
      const csvContent = [headers, ...csvRows].join("\n");

      return new NextResponse(csvContent, {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="roster_${eventId}.csv"`,
        },
      });
    }

    return NextResponse.json({
      success: true,
      eventId,
      exportedAt: new Date().toISOString(),
      teamsCount: teams.length,
      participantsCount: flattened.length,
      roster: flattened,
    });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err.message },
      { status: 500 }
    );
  }
}

